#!/bin/sh
# Extracts defined symbols from a linked .dbg binary and emits a relocation-free
# export table in C. The resulting blob uses absolute addresses and lives in
# .rodata so it survives stripping. Optional filtering via EXPORT_PREFIXES
# (pipe-separated regexp, e.g. "rb_|ruby_|Py|lua_|__cosmo"); defaults to no
# filtering (all defined global/weak FUNC/OBJECT symbols).
set -e

if [ $# -ne 2 ]; then
  echo "usage: $0 <binary.dbg> <output.c>" >&2
  exit 64
fi

EXEC="$1"
OUT="$2"

if [ ! -f "$EXEC" ]; then
  echo "error: missing input $EXEC" >&2
  exit 66
fi

FILTER="${EXPORT_PREFIXES:-}"

tmpnames="$(mktemp)"
trap 'rm -f "$tmpnames"' EXIT

# Parse readelf output and keep defined global/weak FUNC/OBJECT symbols.
readelf -W -s "$EXEC" | awk -v filter="$FILTER" '
  $5 ~ /GLOBAL|WEAK/ && ($4 == "FUNC" || $4 == "OBJECT") && $7 != "UND" {
    name = $NF
    if (name == "") next
    if (filter != "" && name !~ ("^(" filter ")")) next
    # Value is column 2 (hex). Keep as-is.
    print name " " $2
  }
' | sort -u >"$tmpnames"

awk '
  BEGIN {
    printf "/* Auto-generated by third_party/cosmo_plugin/export_symbols.sh */\n"
    printf "#include <stddef.h>\n"
    printf "#include <stdint.h>\n\n"
    printf "struct cosmo_export_entry {\n"
    printf "    uint32_t name_off;\n"
    printf "    uint64_t addr;\n"
    printf "};\n\n"
    count = 0
  }
  NF >= 2 && $1 != "" && $2 != "" {
    names[count] = $1
    addrs[count] = $2
    count++
  }
  END {
    printf "static const char __cosmo_exports_names[] __attribute__((section(\".rodata.cosmo_exports\"), aligned(8))) =\n"
    off = 0
    for (i = 0; i < count; i++) {
      esc = names[i]
      gsub(/\\/,"\\\\",esc)
      gsub(/\"/,"\\\"",esc)
      printf "    \"%s\\0\"\n", esc
      off += length(names[i]) + 1
    }
    printf "    \"\"; /* sentinel */\n\n"
    printf "const struct cosmo_export_entry __cosmo_exports[] __attribute__((section(\".rodata.cosmo_exports\"), aligned(8))) = {\n"
    off = 0
    for (i = 0; i < count; i++) {
      printf "    { %uU, 0x%sULL },\n", off, addrs[i]
      off += length(names[i]) + 1
    }
    printf "    { 0, 0 }\n};\n\n"
    printf "const struct cosmo_export_entry *const __cosmo_exports_start __attribute__((section(\".rodata.cosmo_exports\"))) = __cosmo_exports;\n"
    printf "const struct cosmo_export_entry *const __cosmo_exports_end   __attribute__((section(\".rodata.cosmo_exports\"))) = __cosmo_exports + (sizeof(__cosmo_exports)/sizeof(__cosmo_exports[0]));\n"
    printf "const char *const __cosmo_exports_names_start __attribute__((section(\".rodata.cosmo_exports\"))) = __cosmo_exports_names;\n"
    printf "const char *const __cosmo_exports_names_end   __attribute__((section(\".rodata.cosmo_exports\"))) = __cosmo_exports_names + sizeof(__cosmo_exports_names);\n"
  }
' "$tmpnames" >"$OUT"

# Count symbols before temp file cleanup
symbol_count=$(wc -l <"$tmpnames" 2>/dev/null || echo "unknown")
echo "generated $symbol_count symbols to $OUT"
